//! Generate systemd drop-in units that apply an io_uring policy before ExecStart.

use crate::policy::Policy;
use std::path::Path;

/// Render a drop-in `.conf` that runs `iouring-restrict apply` as ExecStartPre.
pub fn render_dropin(policy_path: &Path, restrict_bin: &Path, unit_comment: &str) -> String {
    let policy = policy_path.display();
    let bin = restrict_bin.display();
    format!(
        "# Generated by iouring-restrict-systemd\n\
         # {unit_comment}\n\
         # Gap: systemd.directives has no RestrictIOUring= (verified 2026-10).\n\
         # This drop-in approximates it via ExecStartPre until upstream lands.\n\
         [Service]\n\
         # Fail the unit if the applicator cannot enforce (no silent skip).\n\
         ExecStartPre={bin} apply --profile {policy} --fail-without-kernel-support\n\
         # Document intended directive name for operators / future systemd:\n\
         # RestrictIOUring=path-or-profile  (NOT IMPLEMENTED upstream)\n"
    )
}

/// Validate a drop-in string has required keys.
pub fn validate_dropin(text: &str) -> Result<(), String> {
    if !text.contains("[Service]") {
        return Err("missing [Service]".into());
    }
    if !text.contains("ExecStartPre=") {
        return Err("missing ExecStartPre=".into());
    }
    if !text.contains("apply --profile") {
        return Err("ExecStartPre must call apply --profile".into());
    }
    if !text.contains("--fail-without-kernel-support") {
        return Err("must fail hard without kernel support".into());
    }
    Ok(())
}

/// Self-test of "retention" contract in userspace (no real exec):
/// simulate restrict → use → exec → recheck markers.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetentionSim {
    pub restricted_before_exec: bool,
    pub still_restricted_after_exec: bool,
}

pub fn simulate_retention(policy: &Policy, survive_exec: bool) -> RetentionSim {
    let _ = policy;
    // Userspace stand-in for CVE-2026-80713 exec-retention concern:
    // if survive_exec=false, post-exec marker clears (bug); true = retained.
    RetentionSim {
        restricted_before_exec: true,
        still_restricted_after_exec: survive_exec,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::policy::Policy;
    use std::path::PathBuf;

    #[test]
    fn dropin_valid() {
        let t = render_dropin(
            Path::new("/etc/iouring/default.json"),
            Path::new("/usr/bin/iouring-restrict"),
            "demo unit",
        );
        validate_dropin(&t).unwrap();
        assert!(t.contains("RestrictIOUring="));
    }

    #[test]
    fn retention_positive() {
        let p = Policy::parse_json(include_str!("../fixtures/default.json")).unwrap();
        let s = simulate_retention(&p, true);
        assert!(s.still_restricted_after_exec);
    }

    #[test]
    fn retention_detects_loss() {
        let p = Policy::parse_json(r#"{"defaultAction":"deny","ops":["IORING_OP_NOP"]}"#).unwrap();
        let s = simulate_retention(&p, false);
        assert!(!s.still_restricted_after_exec);
        let _ = PathBuf::from(".");
    }
}
